import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, float, smoothstep, mix, uniform, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color, DoubleSide } = ctx.THREE;

  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#111117',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  const RIBBON_W = 7.0;
  const RIBBON_H = 0.35;

  // ---- Backdrop stage plane (vertical gradient of the stage color) ----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const vy = uv().y;
    const top = vec3(0.055, 0.055, 0.075);
    const bot = vec3(0.02, 0.02, 0.03);
    backdropMat.colorNode = mix(bot, top, smoothstep(0.0, 1.0, vy));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---- Ribbon rail plane ----
  const railGeo = new PlaneGeometry(RIBBON_W, RIBBON_H);
  const railMat = new MeshStandardNodeMaterial();
  railMat.roughness = 0.6;
  railMat.metalness = 0.2;
  railMat.side = DoubleSide;
  {
    const surfaceCol = new Color(colors.surface || '#111117');
    const base = vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b);
    const hair = vec3(0.137, 0.137, 0.169); // #23232b
    const vy = uv().y;
    // top & bottom hairlines
    const topLine = smoothstep(0.982, 0.99, vy);
    const botLine = float(1.0).sub(smoothstep(0.01, 0.018, vy));
    const lineMask = topLine.max(botLine);
    railMat.colorNode = mix(base, hair, lineMask);

    // edge fade alpha: fade at left/right ends into stage
    const vx = uv().x;
    const leftFade = smoothstep(0.0, 0.09, vx);
    const rightFade = float(1.0).sub(smoothstep(0.91, 1.0, vx));
    railMat.opacityNode = leftFade.min(rightFade);
    railMat.transparent = true;
  }
  const rail = new Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0);
  group.add(rail);

  // ---- Ticker figures ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const figureStrings = items.length
    ? items.map((it) => (typeof it === 'string' ? it : it.text))
    : [
        'CAL NA-01 BEAT 28800 VPH',
        'POWER RESERVE 72H',
        'CASE 40.5 MM 904L',
        'REF 5811 IN STOCK',
        'WAITLIST 1204',
        'NEXT FITTING JUL 18'
      ];

  // Build one content strip: text + accent tick between entries
  function buildStrip() {
    const strip = new Group();
    let cursor = 0;
    const gap = 0.5;
    const tickW = 0.02;
    const tickH = 0.14;
    const charW = 0.075; // approx mono advance at fontSize used

    const tickMats = [];
    const accentCol = new Color(colors.accent || '#ff2a38');

    figureStrings.forEach((str, i) => {
      const label = ctx.fontAtlas.createText(str, {
        fontSize: 48,
        color: colors.paper || '#e8ecf2',
        align: 'left',
        letterSpacingPx: 3
      });
      const textWidth = str.length * charW;
      label.position.set(cursor, 0, 0.02);
      label.scale.setScalar(0.0032);
      strip.add(label);
      cursor += textWidth + gap;

      // accent tick
      const tickGeo = new PlaneGeometry(tickW, tickH);
      const tickMat = new MeshStandardNodeMaterial();
      tickMat.colorNode = vec3(accentCol.r, accentCol.g, accentCol.b);
      tickMat.emissiveNode = vec3(accentCol.r, accentCol.g, accentCol.b).mul(1.5);
      const tick = new Mesh(tickGeo, tickMat);
      tick.position.set(cursor, 0, 0.02);
      strip.add(tick);
      tickMats.push(tickMat);
      cursor += gap;
    });

    strip.userData.width = cursor;
    strip.userData.tickMats = tickMats;
    return strip;
  }

  const stripA = buildStrip();
  const stripLen = stripA.userData.width;
  const stripB = buildStrip();

  const scroller = new Group();
  stripA.position.x = -stripLen / 2;
  stripB.position.x = -stripLen / 2 + stripLen;
  scroller.add(stripA);
  scroller.add(stripB);
  scroller.position.z = 0.0;
  group.add(scroller);

  // ---- Edge fade masks (foreground planes fading figures at ends) ----
  const maskGeo = new PlaneGeometry(0.6, RIBBON_H + 0.02);
  const bgCol = new Color(colors.background || '#0b0b10');

  function makeMask(flip) {
    const mat = new MeshBasicNodeMaterial();
    const vx = uv().x;
    // opaque at outer edge, transparent toward center
    const a = flip ? smoothstep(0.0, 1.0, vx) : float(1.0).sub(smoothstep(0.0, 1.0, vx));
    mat.colorNode = vec3(bgCol.r, bgCol.g, bgCol.b);
    mat.opacityNode = a;
    mat.transparent = true;
    const m = new Mesh(maskGeo, mat);
    m.position.set(flip ? RIBBON_W / 2 - 0.3 : -RIBBON_W / 2 + 0.3, 0, 0.1);
    return m;
  }
  const maskL = makeMask(false);
  const maskR = makeMask(true);
  group.add(maskL);
  group.add(maskR);

  // ---- Lighting (rim/accent local) ----
  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(2.5, 3, 4);
  group.add(key);

  const rim = new DirectionalLight(new Color(colors.accent || '#ff2a38'), 0.7);
  rim.position.set(-3, -1.5, 3);
  group.add(rim);

  // ---- Constant-velocity scroll timeline (linear, leftward) ----
  const speed = config.cinematicPrimitives?.[0]?.params?.speed ?? 0.4;
  const period = stripLen / speed;

  const scrollTl = gsap.timeline({ repeat: -1 });
  scrollTl.fromTo(
    scroller.position,
    { x: 0 },
    { x: -stripLen, duration: period, ease: 'none' }
  );

  // entrance
  const introTl = gsap.timeline();
  introTl.fromTo(
    group.position,
    { y: 0.2 },
    { y: 0, duration: 0.7, ease: 'power3.out' }
  );
  rail.scale.set(1, 1, 1);

  // ---- Apply cinematic primitives ----
  const primHandles = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      try {
        const h = fn(scroller, p.params || {});
        if (h) primHandles.push(h);
      } catch (e) {
        /* ignore primitive runtime issues */
      }
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    scrollTl.kill();
    introTl.kill();
    primHandles.forEach((h) => h?.cleanup && h.cleanup());

    group.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material?.dispose?.();
      }
    });
  };

  return group;
}
